const fs = require('fs');
const path = require('path');

const filePath = path.join(__dirname, './generated-component-context.ts');
const fileContent = `// WARNING: This file is a placeholder for development.
// It will be overwritten by the Angular compiler during the build process.
// Do not edit this file directly or commit it to source control.

export interface ComponentContext {
  name: string;
  description: string;
  type: 'dynamicComponent';
  inputs: { [key: string]: Input; }
}

export interface Input {
  type: string;
  description: string;
  required?: boolean;
}

export const COMPONENT_CONTEXT_DATA: ComponentContext[] = [];
`;

// Create the placeholder ONLY if the file does not already exist
if (!fs.existsSync(filePath)) {
  fs.writeFileSync(filePath, fileContent, 'utf8');
  console.log(`
  -----------------------------------------------------------------------
  Created placeholder for 'generated-component-context.ts'.
  This file is gitignored and will be overwritten by the compiler.
  -----------------------------------------------------------------------
  `);
}
